
CREATE TABLE IF NOT EXISTS `gitRepositories` (`id` int AUTO_INCREMENT PRIMARY KEY, `projectId` int NOT NULL, `provider` varchar(32) NOT NULL DEFAULT 'github', `repositoryUrl` varchar(500) NOT NULL, `owner` varchar(160) NOT NULL, `name` varchar(160) NOT NULL, `defaultBranch` varchar(160) NOT NULL DEFAULT 'main', `connected` boolean NOT NULL DEFAULT false, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `gitBranches` (`id` int AUTO_INCREMENT PRIMARY KEY, `projectId` int NOT NULL, `name` varchar(160) NOT NULL, `baseSnapshotId` int NOT NULL, `headSnapshotId` int NOT NULL, `protected` boolean NOT NULL DEFAULT false, `isDefault` boolean NOT NULL DEFAULT false, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `gitCommits` (`id` int AUTO_INCREMENT PRIMARY KEY, `projectId` int NOT NULL, `branchId` int NOT NULL, `parentCommitId` int NULL, `snapshotId` int NOT NULL, `message` varchar(240) NOT NULL, `treeHash` varchar(64) NOT NULL, `authorUserId` int NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `gitPullRequests` (`id` int AUTO_INCREMENT PRIMARY KEY, `projectId` int NOT NULL, `sourceBranchId` int NOT NULL, `targetBranchId` int NOT NULL, `title` varchar(240) NOT NULL, `description` text NULL, `status` varchar(32) NOT NULL DEFAULT 'open', `conflictsJson` text NULL, `providerNumber` int NULL, `providerUrl` varchar(500) NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX `gitBranches_project_name_uq` ON `gitBranches` (`projectId`,`name`);


